# Statuts de mission où l'ancien modèle montrait les livrables au client.
CLIENT_SIDE_MISSION_STATUSES = ("envoye_client", "valide", "corrections", "publie", "termine")


def split_validations(apps, schema_editor):
    """Jusqu'ici `status` mélangeait la décision de l'agence et celle du
    client. Un livrable déjà envoyé (mission côté client, avec un lien) :
    l'ancien statut était la décision du client, et l'agence l'avait
    forcément validé pour l'envoyer. Un livrable encore interne : on le
    remet en revue agence plutôt que de l'exposer au client du jour au
    lendemain (sauf s'il est déjà publié)."""
    Deliverable = apps.get_model("deliverables", "Deliverable")
    sent = Deliverable.objects.filter(mission__status__in=CLIENT_SIDE_MISSION_STATUSES).exclude(
        url=""
    )
    for d in sent:
        d.client_status = d.status
        d.status = "valide"
        d.save(update_fields=["status", "client_status"])
    Deliverable.objects.exclude(pk__in=sent.values("pk")).filter(
        status="valide", published_at__isnull=True
    ).update(status="en_attente")


